const g=__G.game,G=__G.city.graph; g.tp(30,-6,-Math.PI/2); __G.step(2); g.carNearPlayer('sport',3); g.toggleCar(); const v=g.P.car; v.place(30,-1.75,-Math.PI/2); v.vx=0; v.vz=0;
const E=G.edges.filter(e=>e.road&&e.road.id==='cw1'); let P=[]; for(const e of E) P.push(...e.pts); P.sort((a,b)=>b[0]-a[0]); const C=[0]; for(let i=1;i<P.length;i++) C.push(C[i-1]+Math.hypot(P[i][0]-P[i-1][0],P[i][1]-P[i-1][1]));
const at=(s)=>{ s=Math.max(0,Math.min(C[C.length-1],s)); let i=0; while(i<C.length-2&&C[i+1]<s) i++; const a=P[i],b=P[i+1]; const l=C[i+1]-C[i]||1; const t=(s-C[i])/l; return {x:a[0]+(b[0]-a[0])*t,z:a[1]+(b[1]-a[1])*t,tx:(b[0]-a[0])/l,tz:(b[1]-a[1])/l}; };
const near=(x,z)=>{ let bi=0,bd=1e18; for(let i=0;i<P.length;i++){ const d=(P[i][0]-x)**2+(P[i][1]-z)**2; if(d<bd){bd=d;bi=i;} } return C[bi]; };
const log=[]; let maxSp=0; for(let i=0;i<1800;i++){ let tx,tz; if(v.x>-22){tx=v.x-20; tz=-1.75;} else { const a=at(near(v.x,v.z)+18); tx=a.x-a.tz*5.25; tz=a.z+a.tx*5.25; } const ang=Math.atan2(tx-v.x,tz-v.z)-v.yaw; const aw=Math.atan2(Math.sin(ang),Math.cos(ang)); g.override={throttle: Math.abs(v.speed)<22?1:0.2, steer: Math.max(-1,Math.min(1,aw*2.2))}; __G.step(1); maxSp=Math.max(maxSp,v.speed*3.6); if(i%60==0) log.push([Math.round(v.x),Math.round(v.z),+v.y.toFixed(2),Math.round(v.speed*3.6),Math.round(v.health)]); if(v.x<-1500) break; }
g.override={throttle:0,steer:0,handbrake:true}; __G.step(30); ({log, end:[Math.round(v.x),Math.round(v.z),+v.y.toFixed(2)], maxKmh:Math.round(maxSp), health:Math.round(v.health), inWater:!!v.inWater, area:document.getElementById('area').textContent, state:g.state()})
